type User = {
  id: string;
  displayName: string;
  active: boolean;
  tags: string[];
};

export function formatUser(user: User): string {
  const suffix = user.tags.length ? ` [${user.tags.join(", ")}]` : "";
  return `${user.displayName} (${user.id})${suffix}`;
}

export function isEnabled(user: User): boolean {
  return user.active;
}

